#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (file == NULL) {
        printf("Could not open file %s\n", argv[1]);
        return 1;
    }

    int adj[8][8] = {{0}};
    int indegree[8] = {0};
    int done[8] = {0};
    int stack[10];
    int top = 0;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        int a, b;
        sscanf(line, "%d %d", &a, &b);
        adj[a][b] = 1;
        indegree[b]++;
    }

    fclose(file);

    for (int i = 0; i < 8; i++) {
        if (indegree[i] == 0) {
            stack[top++] = i;
        }
    }

    while (top > 0) {
        int node = stack[--top];
        printf("%d ", node);
        done[node] = 1;

        for (int i = 0; i < 8; i++) {
            if (adj[node][i] && !done[i]) {
                indegree[i]--;
                if (indegree[i] == 0) {
                    stack[top++] = i;
                }
            }
        }
    }

    printf("\n");
    return 0;
}
